#include <algorithm>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

class QuoteListener {
public:
    virtual ~QuoteListener() = default;
    virtual std::string name() const = 0;
    virtual void on_quote(double px) = 0;
};

class FillListener {
public:
    virtual ~FillListener() = default;
    virtual std::string name() const = 0;
    virtual void on_fill(int qty, double px) = 0;
};

class Recorder final : public QuoteListener, public FillListener {
public:
    std::string name() const override { return "recorder"; }
    void on_quote(double px) override {
        ++quotes_;
        high_ = std::max(high_, px);
    }
    void on_fill(int qty, double px) override {
        ++fills_;
        notional_ += std::abs(qty) * px;
    }
    void report() const {
        std::cout << "quotes " << quotes_ << ", high " << high_ << '\n';
        std::cout << "fills " << fills_ << ", notional " << notional_ << '\n';
    }

private:
    int quotes_ = 0;
    double high_ = 0.0;
    int fills_ = 0;
    double notional_ = 0.0;
};

int main() {
    std::cout << std::fixed << std::setprecision(2);
    Recorder recorder;
    std::vector<QuoteListener*> quotes = {&recorder};
    std::vector<FillListener*> fills = {&recorder};
    char kind = ' ';
    while (std::cin >> kind) {
        int qty = 0;
        double px = 0.0;
        if (kind == 'F') {
            std::cin >> qty;
        }
        std::cin >> px;
        if (kind == 'Q') {
            for (QuoteListener* l : quotes) {
                l->on_quote(px);
            }
        } else {
            for (FillListener* l : fills) {
                l->on_fill(qty, px);
            }
        }
    }
    std::cout << "quote listeners:";
    for (const QuoteListener* l : quotes) {
        std::cout << ' ' << l->name();
    }
    std::cout << "\nfill listeners:";
    for (const FillListener* l : fills) {
        std::cout << ' ' << l->name();
    }
    std::cout << '\n';
    recorder.report();
    return 0;
}
